const CI_BASELINE='2127b1a7ebd40e5b9ee7d010e72e75d4b1cb3e9f';
function rehash(value,key){const {[key]:ignored,...body}=value;value[key]=installHash(installJson(body));}
function fixture(){
 const f=installationFixture(),run={...f.run,id:refs.buildRunId,head_sha:refs.controller,repository:{id:REPOSITORY_ID,full_name:REPOSITORY},workflow_id:WORKFLOW_ID,path:WORKFLOW_PATH,head_branch:'alpha',event:'workflow_dispatch',updated_at:new Date(f.now-500).toISOString()};
 const active=['resolve','build','deployment-hold'],skipped=['typecheck','migrations','runner-diagnostics','controller-tests','plan','test','browser','verify'];
 const jobs=[...active,...skipped].map((name,i)=>({id:200+i,name,run_id:run.id,run_attempt:1,head_sha:refs.controller,head_branch:'alpha',status:'completed',conclusion:active.includes(name)?'success':'skipped',started_at:f.producer.started_at,completed_at:f.producer.completed_at,steps:name==='resolve'?[{name:'Refuse invalid build-only execution',conclusion:'success'}]:name==='build'?[{name:'Canonical System Testing production build and byte bundle',conclusion:'success'},{name:'Publish mandatory canonical build packet',conclusion:'success'}]:[]}));
 const artifact={id:456,name:BUILD_ARTIFACT,digest:'sha256:'+'f'.repeat(64),expired:false,size_in_bytes:100,created_at:f.producer.completed_at,expires_at:new Date(f.now+86400000).toISOString(),workflow_run:{id:run.id,repository_id:REPOSITORY_ID,head_repository_id:REPOSITORY_ID,head_sha:refs.controller,head_branch:'alpha'}};
 const pass=(path,originCandidate,engine)=>({path,originCandidate,...(engine?{engine}:{}),state:'PASSED',passingAssertions:path==='test/rewards-bonus-budget.dom.test.tsx'?5:3,failedAssertions:0});
 const names=['test/rewards-bonus-budget.dom.test.tsx',...Array.from({length:2036},(_,i)=>'test/file-'+i+'.test.ts')];
 const acceptance={kind:'COMBINED_REQUIRED_BONUS_COVERAGE_WITH_OWNER_EXCEPTION',policy:'runtime-owner-exception/v1',result:'ACCEPTED_WITH_OWNER_EXCEPTION',candidate:refs.candidate,stagingBaseline:refs.base,historicalAuthorizationSha256:refs.historicalAuthorizationSha256,historicalAcceptanceSha256:'a'.repeat(64),ioContinuitySha256:'b'.repeat(64),experienceEvidenceSha256:'c'.repeat(64),fullGatePassCreated:false,createsNewFullPassBaseline:false,releaseAuthorized:false,postDeployAcceptanceRequired:true,
  originalFailedRun:{runId:40444007805,conclusion:'failure'},actualImpact:{base:refs.base,head:refs.candidate,actualPolicy:3,changedFiles:['app/rewards/[unitId]/bonus-budget.tsx','test/rewards-bonus-budget.dom.test.tsx'],plan:{policyVersion:3,tier:'impact',risk:'moderate',browser:true,run:names.slice(0,1772),fingerprint:'c66e7f43f048a2a53c86205e31366d99bdd28214606a61d09d623638c51e7cc3'}},
  wholeCompiler:{kind:'AUTHENTICATED_WHOLE_COMPILER_ONLY_NOT_TEST_COVERAGE',candidate:refs.candidate,controller:refs.controller,runId:40507897305,conclusion:'success',runtime:{node:'22.23.3',platform:'linux',arch:'x64'},logSha256:'d'.repeat(64)},
  ordinaryFiles:names.map((path,i)=>pass(path,i<859?refs.candidate:refs.base)),browserFiles:['chromium','firefox','webkit'].flatMap(engine=>Array.from({length:19},(_,i)=>pass('test/browser-'+i+'.browser.test.tsx',refs.candidate,engine)))};
 rehash(acceptance,'acceptanceSha256');
 const baselineAdvance={kind:'FORWARD_STAGING_BASELINE_SOURCE_PREFIX_NOT_CI_RECEIPT',candidate:refs.candidate,ciBaseline:CI_BASELINE,deploymentBaseline:refs.base,ciMigrationCount:498,deploymentMigrationCount:503,candidateMigrationCount:503,originalCiBaselinePreserved:true,requiresFreshActualLedgerAndBuildBinding:true,requiresOriginalCIAuthentication:true,releaseAuthorized:false};rehash(baselineAdvance,'proofSha256');
 return {snapshot:{run,jobs,artifacts:[artifact]},now:f.now,baselineBuildId:refs.baselineBuildId,environmentSha256:f.environmentSha256,acceptance,
  evidence:{kind:'AUTHENTICATED_BONUS_OWNER_EXCEPTION_AND_CANONICAL_BUILD',sha:refs.candidate,controller:refs.controller,controllerBranch:'alpha',baseline:CI_BASELINE,deploymentBaseline:refs.base,runId:run.id,artifact:{id:artifact.id,digest:artifact.digest},baselineAdvance,build:{...f.evidence.build,source:refs.candidate,controller:refs.controller,runId:run.id,nextBuildId:BONUS_BUILD_ID}}};
}
test('issues only a fresh exact Bonus staging byte grant, preserving existing stricter protocols',()=>{
 const f=fixture(),g=createBonusInstallGrant(f),again=createBonusInstallGrant(f);
 assert.equal(g.source,refs.candidate);assert.equal(g.baseline,refs.base);assert.equal(g.baselineBuildId,refs.baselineBuildId);assert.equal(g.build.nextBuildId,BONUS_BUILD_ID);assert.equal(g.target,'alpha-staging');assert.equal(g.result,undefined);assert.notEqual(g.installId,again.installId);assert.equal(Date.parse(g.expiresAt)-f.now,30*60000);
 assert.equal(f.acceptance.fullGatePassCreated,false);assert.equal(f.acceptance.originalFailedRun.conclusion,'failure');
 assert.throws(()=>inspectBuildOnlySnapshot({...f.snapshot,expected:{candidate:refs.candidate,controller:refs.controller,runId:refs.buildRunId},now:f.now}));assert.throws(()=>createRuntimeInstallGrant(f));
});
for(const [name,change] of [
 ['ordinary omission',f=>f.acceptance.ordinaryFiles.pop()],['ordinary duplicate',f=>f.acceptance.ordinaryFiles[1]=f.acceptance.ordinaryFiles[0]],['nonexecuted case',f=>f.acceptance.ordinaryFiles[0].state='PENDING'],['failed assertion',f=>f.acceptance.ordinaryFiles[0].failedAssertions=1],['unproved current consumer',f=>f.acceptance.ordinaryFiles[1].originCandidate=refs.base],['lost literal money case',f=>f.acceptance.ordinaryFiles[0].passingAssertions=4],
 ['browser omission',f=>f.acceptance.browserFiles.pop()],['duplicate browser file',f=>f.acceptance.browserFiles[1]=f.acceptance.browserFiles[0]],['historical browser carry',f=>f.acceptance.browserFiles[0].originCandidate=refs.base],['mismatched engine files',f=>f.acceptance.browserFiles[19].path='test/unregistered.browser.test.tsx'],
 ['fake full PASS',f=>f.acceptance.fullGatePassCreated=true],['new baseline',f=>f.acceptance.createsNewFullPassBaseline=true],['erased original failure',f=>f.acceptance.originalFailedRun.conclusion='success'],['foreign historical authorization',f=>f.acceptance.historicalAuthorizationSha256='0'.repeat(64)],['different policy',f=>f.acceptance.actualImpact.actualPolicy=4],['changed impact fingerprint',f=>f.acceptance.actualImpact.plan.fingerprint='0'.repeat(64)],['missing IO proof',f=>delete f.acceptance.ioContinuitySha256],['missing experience',f=>delete f.acceptance.experienceEvidenceSha256],
 ['wrong compiler source',f=>f.acceptance.wholeCompiler.candidate=refs.base],['wrong compiler runtime',f=>f.acceptance.wholeCompiler.runtime.node='22.23.4'],['wrong installed baseline build',f=>f.baselineBuildId='another-build'],['wrong candidate',f=>f.evidence.sha=refs.base],['wrong controller',f=>f.evidence.controller=refs.base],['wrong CI baseline',f=>f.evidence.baseline=refs.base],['wrong new build',f=>f.evidence.build.nextBuildId='another-build'],['unverified build inputs',f=>f.evidence.build.canonicalCandidateInputsVerified=false],
 ['changed migration count',f=>f.evidence.baselineAdvance.candidateMigrationCount=504],['rewritten CI history',f=>f.evidence.baselineAdvance.originalCiBaselinePreserved=false],['missing fresh ledger requirement',f=>f.evidence.baselineAdvance.requiresFreshActualLedgerAndBuildBinding=false],['changed artifact',f=>f.evidence.artifact.id=999],['skipped actual build',f=>f.snapshot.jobs.find(j=>j.name==='build').conclusion='skipped'],['rerun origin',f=>f.snapshot.run.run_attempt=2],['foreign branch',f=>f.snapshot.run.head_branch='feature'],['expired evidence',f=>f.now+=86400001],['invalid environment binding',f=>f.environmentSha256='not-a-digest']
])test('refuses '+name+' even when caller recomputes metadata hashes',()=>{const f=fixture();change(f);rehash(f.acceptance,'acceptanceSha256');rehash(f.evidence.baselineAdvance,'proofSha256');assert.throws(()=>createBonusInstallGrant(f));});
test('also refuses an altered acceptance hash without accepting a caller assertion',()=>{const f=fixture();f.acceptance.acceptanceSha256='0'.repeat(64);assert.throws(()=>createBonusInstallGrant(f));});
